  'rep-honest-results': { label: 'Honest reporting', description: 'Writes up results with the measurement method and the limits of their scope; separates the simulator from reality.' },
  'ai-concepts': { label: 'AI concepts', description: 'Knows the difference between artificial intelligence, machine learning and language models.' },
  'ai-simulation-literacy': { label: 'Simulation literacy', description: 'Tells real calculation apart from steps labelled as simulation/template; does not mistake them for a model\'s answer.' },
