  'ai-fewshot': { label: 'Teaching with a few examples', description: 'Tells zero-shot and few-shot prompts apart; writes balanced, consistent, correct examples; knows how this differs from fine-tuning.' },
  'ai-structured-output': { label: 'Structured output', description: 'Asks for a format a program will read (JSON); knows key names and the rules for valid JSON.' },
