  'ai-rag-eval': { label: 'Measuring RAG', description: 'Measures retrieval accuracy and answer faithfulness separately; links an error to the right step.' },
  'agent-tools': { label: 'Tool use', description: 'Knows the model-tool split: the model requests a call, the application runs the tool, and the result comes back as an observation; writes a tool call in the form `arac(girdi)`.' },
  'agent-loop': { label: 'Agent loop', description: 'Orders the think-act-observe loop, carries step results with `$n` and `$son`, and knows the limits of a scripted agent.' },
  'agent-limits': { label: 'Errors, limits and stopping', description: 'Explains the step limit, error observations and stopping conditions (result, error, limit); compares the `tekrar` total with the wall.' },
  'agent-safety': { label: 'Agent safety', description: 'Applies the principles of measure first, safety margin, least privilege and human approval.' },
  'agent-plan': { label: 'Agent plan and calculation', description: 'Builds a measure-calculate-advance plan with step numbers and correctly calculates the percentage remaining and the margin.' },
  'agent-eval': { label: 'Measuring an agent', description: 'Knows the difference in reliability between a scripted agent and one that uses a model; explains why an agent is measured with repeated trials.' },
  'ai-hallucination': { label: 'Recognising hallucination', description: 'Compares a claim in the output with a source and sorts it as consistent, contradicting or not in the source.' },
  'ai-verify': { label: 'Verification', description: 'Checks model output by looking at the source or by running the code.' },
  'ai-eval-rate': { label: 'Rates and accuracy calculation', description: 'Calculates accuracy, error rate and the expected number of errors from the number of cases.' },
  'ai-privacy': { label: 'Privacy', description: 'Knows what information should not be typed into a service; anonymises data.' },
  'ai-attribution': { label: 'Sources and honesty', description: 'States when AI has helped and verifies sources personally.' },
  'ai-bias': { label: 'Measuring bias', description: 'Shows bias by comparing accuracy across groups.' },
  'ai-rule-vs-model': { label: 'Rule or model?', description: 'Explains the reasons for leaving a decision to a rule or to a model, and the choice of threshold.' },
  'ai-agent-script': { label: 'Agent script', description: 'Reads and traces an agent script (tool calls, if, $son) and finds its bugs.' },
  'ai-safety-layer': { label: 'Safety layer', description: 'Knows that a hard limit must be enforced independently of the model.' },
  'ai-human-oversight': { label: 'Human oversight', description: 'Applies the human-in-the-loop and safe default patterns.' },
  'ai-risk-assess': { label: 'Risk assessment', description: 'Assesses the risk of automation by reversibility, the people affected and the cost of errors.' },
  'ai-portfolio': { label: 'Portfolio and evidence', description: 'Writes a short portfolio that backs up its claims with numbers and evidence.' },
  'ai-honesty': { label: 'Honest reporting', description: 'Clearly separates real calculation, simulation and missing parts.' },
  'jr-sequence': { label: 'Command order', description: 'Knows that commands run in order from top to bottom and that changing the order changes the result.' },
  'jr-motion': { label: 'Movement and turning', description: 'Moves the robot with the Forward, Back, Turn right and Turn left blocks; counts steps and predicts the direction of a turn.' },
