  'jr-looks': { label: 'Looks and sound', description: 'Knows what the Say, Grow, Shrink and Play sound blocks do.' },
  'jr-events': { label: 'Events', description: 'Knows that a character does nothing without an event (a tap or the flag) and that the event starts the script.' },
  'jr-sprite-scripts': { label: 'A character\'s own scripts', description: 'Knows that each character has its own scripts and that a script is written for the selected character.' },
  'jr-timing': { label: 'Wait block', description: 'Knows that the Wait block delays the next block and sets up the order of speech.' },
  'jr-pages': { label: 'Pages and scenes', description: 'Adds pages and chooses backgrounds; knows that the Go to page block moves to a numbered page and that a script must be started on the new page.' },
  'jr-planning': { label: 'Story plan', description: 'Plans a story in advance by splitting it into scenes with a beginning, middle and end.' },
  'jr-debug': { label: 'Debugging', description: 'Looks for the bug in a program that does not work: a missing start block, wrong order, wrong direction and wrong number.' },
  'sh-program': { label: 'Programs and command order', description: 'Knows that a computer carries out commands in order and exactly as written; predicts the result of a block sequence.' },
