  'sh-costume': { label: 'Costumes and animation', description: 'Builds animation by switching costumes; knows that next costume wraps back to the start.' },
  'sh-loop': { label: 'Loops', description: 'Chooses between the repeat and forever blocks; works out the inside and outside of the loop and the number of passes.' },
  'sh-parallel': { label: 'Running in parallel', description: 'Knows that the code of several sprites runs at the same time.' },
  'sh-wait': { label: 'Waiting and timing', description: 'Adds up wait times and calculates speech and animation timing in seconds.' },
  'sh-events': { label: 'Events and hat blocks', description: 'Chooses the correct hat blocks for the green flag, key press and sprite click events.' },
  'sh-sound': { label: 'Sound and instruments', description: 'Knows the difference between start sound and play sound until done, the volume limits and melody timing.' },
  'sh-msg': { label: 'Broadcast messages', description: 'Connects characters by broadcasting and receiving messages; knows that message names must match.' },
  'sh-var': { label: 'Variables', description: 'Creates a variable and updates it with "set to" and "change by"; calculates score, lives and time values.' },
  'sh-cond': { label: 'Conditions', description: 'Uses the if block and comparisons (=, <); writes end conditions correctly.' },
  'sh-random': { label: 'Random numbers', description: 'Knows the range of the random number block (ends included) and the number of possible values.' },
  'sh-clone': { label: 'Clones', description: 'Creates clones, writes the clone\'s code under "when I start as a clone" and calculates the number of clones.' },
  'sh-proc': { label: 'My own block', description: 'Defines a block, calls it and adds inputs; knows that the definition does not run on its own.' },
  'sh-list': { label: 'Lists', description: 'Counts a list\'s items from 1, reads the Nth item and walks through matching lists with an index variable.' },
  'sh-debug': { label: 'Finding bugs (Stage Workshop)', description: 'Finds common bugs in block sequences that do not work: unattached blocks, outside the loop, wrong hat block, missing reset.' },
  'sh-plan': { label: 'Planning and testing', description: 'Plans the project first, starts from the smallest working version, tries things in small steps and gets feedback from a test partner.' },
  'sh-safety': { label: 'Online safety', description: 'Does not put personal information (real name, school, address, photo) in projects or notes.' },
